mapper.select:
SELECT count(*)
  FROM (
         SELECT ifi91_config_id
           FROM ifi91_config_api
          WHERE ifi91_config_id = #{configId}
          UNION ALL
         SELECT ifi95_config_file_id
           FROM ifi95_config_file
          WHERE ifi95_config_id = #{configId}
       ) t

mapper.update:
UPDATE ifi90_config
   SET ifi90_if_cd          = #{r.ifCode}
     , ifi90_if_nm          = #{r.ifName}
     , ifi90_if_type        = #{r.ifType}
     , ifi90_local_host     = #{r.localHost}
     , ifi90_local_port     = #{r.localPort}
     , ifi90_local_account  = #{r.localAccount}
     , ifi90_local_path     = #{r.localPath}
     , ifi90_local_key      = #{r.localKey}
     , ifi90_target_host    = #{r.targetHost}
     , ifi90_target_port    = #{r.targetPort}
     , ifi90_target_account = #{r.targetAccount}
     , ifi90_target_path    = #{r.targetPath}
     , ifi90_target_key1    = #{r.targetKey}
     , ifi90_note           = #{r.note}
 WHERE ifi90_config_id = #{r.configId}

mapper.delete:
DELETE FROM ifi90_config
 WHERE ifi90_config_id IN
#{id}
